type OrderAck { orderId: ID!  status: OrderStatus! }
type Mutation { submitOrder(input: OrderRequestInput!): OrderAck! }

// resolvers are the translator; the domain object never becomes the return shape
export const resolvers = {
  Mutation: { submitOrder: (_: unknown, { input }: any) => toAck(orders.submit(toDomain(input))) },
};
